// Trip pages need six stylesheets. Each extra file is one more request a phone
// must finish before it can paint, so they are served as one file built from
// the sources below. Edit the sources; the bundle is generated by the build.
import {readFile} from 'node:fs/promises';
import path from 'node:path';

// Cascade order: later files override earlier ones, exactly as the old <link> list did.
export const TRIP_STYLES = ['styles.css', 'home.css', 'trip.css', 'trip-detail.css', 'trip-conversion.css', 'trip-page.css'];
export const TRIP_BUNDLE = 'trip-bundle.css';

export async function tripBundle(root) {
  const parts = [];
  for (const file of TRIP_STYLES) parts.push(`/* ${file} */\n${(await readFile(path.join(root, file), 'utf8')).trimEnd()}\n`);
  return `/* Generado por scripts/trip-styles.mjs: edita las hojas de origen, no este archivo. */\n${parts.join('')}`;
}
